WITH latest AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY status ORDER BY end_date DESC, id) AS rank_in_group FROM subscriptions) t WHERE rank_in_group = 1) SELECT s.id, s.customer_id, s.plan, s.end_date, s.monthly_fee, s.status, CASE WHEN plan RLIKE '^(standard|basic)$' THEN 'OTHER_ZONE' WHEN plan RLIKE '^(premium|enterprise)$' THEN 'GROUP_B' ELSE 'CORE' END AS plan_zone, (SELECT SUM(x.balance) FROM accounts x WHERE x.customer_id = s.customer_id) AS sum_account_balance FROM latest s
